-- Frontdesk HMS database schema for PostgreSQL (Supabase or any Postgres 14+).
--
-- The app runs this file itself every time it starts with DATABASE_URL set, so you never have to.
-- It is also safe to paste into the Supabase SQL Editor and run (as often as you like) if you want
-- the tables to exist before the first deploy.
--
-- It holds the same tables as schema.sql plus the SQLite migrations, i.e. database version 2.
-- Do not edit it for later changes: add server/db/migrations/pg/NNN-name.sql (and the SQLite twin
-- server/db/migrations/NNN-name.sql) instead.
--
-- Money is in cents (bigint). Dates are text 'YYYY-MM-DD', times 'YYYY-MM-DD HH:MM' in hotel time.
-- Text uses the "C" collation so sorting and date comparisons match the SQLite version exactly.

CREATE TABLE IF NOT EXISTS app_meta (
  key   text COLLATE "C" PRIMARY KEY,
  value text COLLATE "C" NOT NULL
);

CREATE TABLE IF NOT EXISTS settings (
  key   text COLLATE "C" PRIMARY KEY,
  value text COLLATE "C" NOT NULL                 -- JSON
);

CREATE TABLE IF NOT EXISTS users (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          text COLLATE "C" NOT NULL,
  email         text COLLATE "C" NOT NULL,
  password_hash text COLLATE "C" NOT NULL,
  role          text COLLATE "C" NOT NULL CHECK (role IN ('admin', 'manager', 'frontdesk', 'housekeeping')),
  title         text COLLATE "C" NOT NULL DEFAULT '',
  department    text COLLATE "C" NOT NULL DEFAULT '',
  shift         text COLLATE "C" NOT NULL DEFAULT 'morning' CHECK (shift IN ('morning', 'evening', 'night')),
  code          text COLLATE "C" NOT NULL UNIQUE,   -- short code used on the room board, e.g. 'mv'
  area          text COLLATE "C",                   -- housekeeping area label, e.g. 'Floor 1'
  floor         integer,                            -- housekeeping home floor
  avatar_tone   text COLLATE "C" NOT NULL DEFAULT '',
  active        integer NOT NULL DEFAULT 1,
  must_change_password integer NOT NULL DEFAULT 0,
  created_at    text COLLATE "C" NOT NULL,
  last_login_at text COLLATE "C"
);
CREATE UNIQUE INDEX IF NOT EXISTS users_email ON users (lower(email));

CREATE TABLE IF NOT EXISTS sessions (
  id          text COLLATE "C" PRIMARY KEY,         -- SHA-256 of the cookie value (the raw token is never stored)
  user_id     bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  csrf_token  text COLLATE "C" NOT NULL,
  shift       text COLLATE "C" NOT NULL DEFAULT 'morning',
  remember    integer NOT NULL DEFAULT 0,
  created_at  bigint NOT NULL,                      -- epoch ms
  last_seen   bigint NOT NULL,
  expires_at  bigint NOT NULL,
  ip          text COLLATE "C",
  user_agent  text COLLATE "C"
);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions (user_id);

CREATE TABLE IF NOT EXISTS login_attempts (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email      text COLLATE "C" NOT NULL,
  ip         text COLLATE "C",
  ok         integer NOT NULL,
  created_at bigint NOT NULL                        -- epoch ms
);
CREATE INDEX IF NOT EXISTS login_attempts_lookup ON login_attempts (lower(email), created_at);

CREATE TABLE IF NOT EXISTS room_types (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code            text COLLATE "C" NOT NULL UNIQUE,
  name            text COLLATE "C" NOT NULL,
  base_rate_cents bigint NOT NULL CHECK (base_rate_cents >= 0),
  max_guests      integer NOT NULL CHECK (max_guests BETWEEN 1 AND 12),
  clean_minutes   integer NOT NULL DEFAULT 40,
  service_minutes integer NOT NULL DEFAULT 25,
  sort            integer NOT NULL DEFAULT 0,
  active          integer NOT NULL DEFAULT 1,
  description     text COLLATE "C" NOT NULL DEFAULT '',
  photo           text COLLATE "C" NOT NULL DEFAULT '',
  bed             text COLLATE "C" NOT NULL DEFAULT '',
  size_sqm        integer,
  online          integer NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS rooms (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  number        text COLLATE "C" NOT NULL UNIQUE,
  floor         integer NOT NULL,
  room_type_id  bigint NOT NULL REFERENCES room_types(id),
  hk_status     text COLLATE "C" NOT NULL DEFAULT 'clean' CHECK (hk_status IN ('clean', 'dirty')),
  attendant_id  bigint REFERENCES users(id) ON DELETE SET NULL,
  active        integer NOT NULL DEFAULT 1,
  hk_updated_at text COLLATE "C"
);

-- Out-of-order periods. start_date is the first night off sale, end_date the day it is back.
CREATE TABLE IF NOT EXISTS room_blocks (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  room_id    bigint NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  start_date text COLLATE "C" NOT NULL,
  end_date   text COLLATE "C" NOT NULL CHECK (end_date > start_date),
  reason     text COLLATE "C" NOT NULL,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at text COLLATE "C" NOT NULL
);
CREATE INDEX IF NOT EXISTS room_blocks_room ON room_blocks (room_id, start_date, end_date);

CREATE TABLE IF NOT EXISTS rate_plans (
  id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code             text COLLATE "C" NOT NULL UNIQUE,
  name             text COLLATE "C" NOT NULL,
  adjust_type      text COLLATE "C" NOT NULL CHECK (adjust_type IN ('amount', 'percent')),
  adjust_value     integer NOT NULL,                -- cents per night, or whole percent (e.g. -12)
  description      text COLLATE "C" NOT NULL DEFAULT '',
  bookable         integer NOT NULL DEFAULT 1,      -- offered on the new booking form
  sort             integer NOT NULL DEFAULT 0,
  active           integer NOT NULL DEFAULT 1,
  free_cancel_days integer,                         -- NULL means non-refundable
  online           integer NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS extras (
  id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code        text COLLATE "C" NOT NULL UNIQUE,
  name        text COLLATE "C" NOT NULL,
  price_cents bigint NOT NULL CHECK (price_cents >= 0),
  per         text COLLATE "C" NOT NULL CHECK (per IN ('stay', 'night')),
  sort        integer NOT NULL DEFAULT 0,
  active      integer NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS sources (
  id        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name      text COLLATE "C" NOT NULL UNIQUE,
  kind      text COLLATE "C" NOT NULL DEFAULT 'direct' CHECK (kind IN ('direct', 'ota', 'corporate', 'walk_in')),
  sort      integer NOT NULL DEFAULT 0,
  form_sort integer,                                -- position on the new booking form (NULL = not offered)
  active    integer NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS guests (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name        text COLLATE "C" NOT NULL,
  last_name         text COLLATE "C" NOT NULL,
  email             text COLLATE "C",
  phone             text COLLATE "C",
  city              text COLLATE "C",
  company           text COLLATE "C",
  vip               integer NOT NULL DEFAULT 0,
  corporate         integer NOT NULL DEFAULT 0,
  preferences       text COLLATE "C" NOT NULL DEFAULT '{}',  -- JSON: { room: [], comfort: [], dining: [], service: [] }
  prior_stays       integer NOT NULL DEFAULT 0,     -- history imported from before this system
  prior_nights      integer NOT NULL DEFAULT 0,
  prior_spend_cents bigint NOT NULL DEFAULT 0,
  created_at        text COLLATE "C" NOT NULL,
  updated_at        text COLLATE "C",
  -- registration details (India: GRC; foreign guests: passport and visa for Form III)
  nationality       text COLLATE "C",               -- ISO 3166 code, e.g. 'IN'
  address           text COLLATE "C",
  date_of_birth     text COLLATE "C",
  id_type           text COLLATE "C",
  id_number         text COLLATE "C",
  passport_number   text COLLATE "C",
  visa_number       text COLLATE "C",
  visa_type         text COLLATE "C",
  visa_valid_until  text COLLATE "C",
  arrived_in_india  text COLLATE "C",
  port_of_arrival   text COLLATE "C",
  gstin             text COLLATE "C"                -- company GSTIN for B2B invoices
);
CREATE INDEX IF NOT EXISTS guests_name ON guests (last_name, first_name);
CREATE INDEX IF NOT EXISTS guests_email ON guests (lower(email));

CREATE TABLE IF NOT EXISTS guest_notes (
  id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  guest_id    bigint NOT NULL REFERENCES guests(id) ON DELETE CASCADE,
  author_id   bigint REFERENCES users(id) ON DELETE SET NULL,
  author_name text COLLATE "C" NOT NULL,
  body        text COLLATE "C" NOT NULL,
  created_at  text COLLATE "C" NOT NULL
);
CREATE INDEX IF NOT EXISTS guest_notes_guest ON guest_notes (guest_id, created_at);

CREATE TABLE IF NOT EXISTS reservations (
  id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  confirmation        text COLLATE "C" NOT NULL UNIQUE,
  guest_id            bigint NOT NULL REFERENCES guests(id),
  room_type_id        bigint NOT NULL REFERENCES room_types(id),
  room_id             bigint REFERENCES rooms(id),
  arrival             text COLLATE "C" NOT NULL,
  departure           text COLLATE "C" NOT NULL CHECK (departure > arrival),
  adults              integer NOT NULL DEFAULT 1 CHECK (adults >= 1),
  children            integer NOT NULL DEFAULT 0 CHECK (children >= 0),
  rate_plan_id        bigint REFERENCES rate_plans(id),
  nightly_rate_cents  bigint NOT NULL,
  source_id           bigint REFERENCES sources(id),
  status              text COLLATE "C" NOT NULL CHECK (status IN ('tentative', 'confirmed', 'checked_in', 'checked_out', 'cancelled', 'no_show')),
  eta                 text COLLATE "C",
  checked_in_at       text COLLATE "C",
  checked_out_at      text COLLATE "C",
  cancelled_at        text COLLATE "C",
  tags                text COLLATE "C" NOT NULL DEFAULT '[]',  -- JSON: early, late, anniversary, first-stay
  notes               text COLLATE "C" NOT NULL DEFAULT '',    -- internal note (tape chart)
  requests            text COLLATE "C" NOT NULL DEFAULT '',    -- guest requests from the booking form
  room_total_cents    bigint NOT NULL,
  tax_cents           bigint NOT NULL,
  extras_cents        bigint NOT NULL DEFAULT 0,
  total_cents         bigint NOT NULL,
  paid_cents          bigint NOT NULL DEFAULT 0,
  created_by          bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at          text COLLATE "C" NOT NULL,
  updated_at          text COLLATE "C",
  purpose             text COLLATE "C",
  arriving_from       text COLLATE "C",
  going_to            text COLLATE "C",
  grc_at              text COLLATE "C",
  grc_by              bigint REFERENCES users(id) ON DELETE SET NULL,
  form3_arrival_ref   text COLLATE "C",
  form3_arrival_at    text COLLATE "C",
  form3_departure_ref text COLLATE "C",
  form3_departure_at  text COLLATE "C",
  booked_online       integer NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS reservations_dates ON reservations (arrival, departure);
CREATE INDEX IF NOT EXISTS reservations_room ON reservations (room_id, arrival, departure);
CREATE INDEX IF NOT EXISTS reservations_guest ON reservations (guest_id);
CREATE INDEX IF NOT EXISTS reservations_status ON reservations (status);

CREATE TABLE IF NOT EXISTS reservation_extras (
  reservation_id bigint NOT NULL REFERENCES reservations(id) ON DELETE CASCADE,
  extra_id       bigint NOT NULL REFERENCES extras(id),
  amount_cents   bigint NOT NULL,
  PRIMARY KEY (reservation_id, extra_id)
);

CREATE TABLE IF NOT EXISTS housekeeping_tasks (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_date    text COLLATE "C" NOT NULL,
  room_id      bigint NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  kind         text COLLATE "C" NOT NULL CHECK (kind IN ('departure', 'stayover', 'maintenance')),
  title        text COLLATE "C" NOT NULL,
  minutes      integer NOT NULL CHECK (minutes > 0),
  attendant_id bigint REFERENCES users(id) ON DELETE SET NULL,
  note         text COLLATE "C",                    -- staff note shown as a chip
  note_tone    text COLLATE "C",                    -- '', 'amber', 'gold', 'blue'
  done_at      text COLLATE "C",
  done_by      bigint REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS housekeeping_tasks_date ON housekeeping_tasks (task_date);

CREATE TABLE IF NOT EXISTS handover_notes (
  id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  author_id   bigint REFERENCES users(id) ON DELETE SET NULL,
  author_name text COLLATE "C" NOT NULL,
  department  text COLLATE "C" NOT NULL,
  lead        text COLLATE "C" NOT NULL,            -- shown in bold
  body        text COLLATE "C" NOT NULL,
  created_at  text COLLATE "C" NOT NULL
);

CREATE TABLE IF NOT EXISTS notifications (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  icon       text COLLATE "C" NOT NULL,
  tone       text COLLATE "C" NOT NULL DEFAULT '',
  title      text COLLATE "C" NOT NULL,
  detail     text COLLATE "C" NOT NULL,
  created_at text COLLATE "C" NOT NULL
);

CREATE TABLE IF NOT EXISTS notification_reads (
  notification_id bigint NOT NULL REFERENCES notifications(id) ON DELETE CASCADE,
  user_id         bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  PRIMARY KEY (notification_id, user_id)
);

-- One row per closed business day (night audit), used for trends.
CREATE TABLE IF NOT EXISTS daily_stats (
  date               text COLLATE "C" PRIMARY KEY,
  rooms_available    integer NOT NULL,
  rooms_sold         integer NOT NULL,
  room_revenue_cents bigint NOT NULL,
  adr_cents          bigint NOT NULL,
  revpar_cents       bigint NOT NULL,
  closed_by          bigint REFERENCES users(id) ON DELETE SET NULL,
  closed_at          text COLLATE "C"
);

-- Revenue by outlet and day (rooms are posted by the night audit; other outlets are entered by staff).
CREATE TABLE IF NOT EXISTS revenue (
  date         text COLLATE "C" NOT NULL,
  outlet       text COLLATE "C" NOT NULL CHECK (outlet IN ('rooms', 'fnb', 'spa')),
  amount_cents bigint NOT NULL,
  PRIMARY KEY (date, outlet)
);

CREATE TABLE IF NOT EXISTS activity_log (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    bigint REFERENCES users(id) ON DELETE SET NULL,
  user_name  text COLLATE "C" NOT NULL,
  action     text COLLATE "C" NOT NULL,
  summary    text COLLATE "C" NOT NULL,
  ip         text COLLATE "C",
  created_at text COLLATE "C" NOT NULL
);
CREATE INDEX IF NOT EXISTS activity_log_time ON activity_log (created_at);

CREATE TABLE IF NOT EXISTS payments (
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reservation_id bigint NOT NULL REFERENCES reservations(id) ON DELETE CASCADE,
  amount_cents   bigint NOT NULL,                   -- negative for a refund
  method         text COLLATE "C" NOT NULL,
  reference      text COLLATE "C" NOT NULL DEFAULT '',
  taken_by       bigint REFERENCES users(id) ON DELETE SET NULL,
  taken_by_name  text COLLATE "C" NOT NULL DEFAULT '',
  created_at     text COLLATE "C" NOT NULL
);
CREATE INDEX IF NOT EXISTS payments_reservation ON payments (reservation_id);

CREATE TABLE IF NOT EXISTS invoices (
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  number         text COLLATE "C" NOT NULL UNIQUE,
  reservation_id bigint NOT NULL REFERENCES reservations(id),
  status         text COLLATE "C" NOT NULL DEFAULT 'issued' CHECK (status IN ('issued', 'cancelled')),
  issued_at      text COLLATE "C" NOT NULL,
  issued_by      bigint REFERENCES users(id) ON DELETE SET NULL,
  data           text COLLATE "C" NOT NULL,         -- JSON snapshot of everything printed on it
  total_cents    bigint NOT NULL,
  cancelled_at   text COLLATE "C"
);
CREATE INDEX IF NOT EXISTS invoices_reservation ON invoices (reservation_id);

CREATE TABLE IF NOT EXISTS outbox (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  to_address text COLLATE "C" NOT NULL,
  subject    text COLLATE "C" NOT NULL,
  body       text COLLATE "C" NOT NULL,
  status     text COLLATE "C" NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'sent', 'failed', 'logged')),
  error      text COLLATE "C",
  created_at text COLLATE "C" NOT NULL,
  sent_at    text COLLATE "C"
);

CREATE TABLE IF NOT EXISTS password_resets (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash text COLLATE "C" NOT NULL UNIQUE,
  expires_at bigint NOT NULL,                       -- epoch ms
  used_at    bigint,
  created_at bigint NOT NULL
);

-- Two small helpers the queries share with SQLite (where server/db/functions.js provides them).
-- leading_int('101') = 101, leading_int('12B') = 12, leading_int('PH-1') = 0: sorts room numbers
-- like numbers without failing on letters (SQLite's CAST(x AS INTEGER) behaviour).
CREATE OR REPLACE FUNCTION leading_int(value text) RETURNS numeric
  LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE SET search_path = ''
  AS $$ SELECT COALESCE(CAST(substring(value FROM '^\s*([+-]?[0-9]+)') AS numeric), 0) $$;

-- days_between('2026-09-24', '2026-09-27') = 3
CREATE OR REPLACE FUNCTION days_between(first_day text, last_day text) RETURNS integer
  LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE SET search_path = ''
  AS $$ SELECT CAST(last_day AS date) - CAST(first_day AS date) $$;

-- Supabase also publishes tables through its Data API. Row level security with no policies keeps
-- every row away from that API (anon / authenticated keys); the app itself connects as the tables'
-- owner and is not affected. On other Postgres servers this changes nothing.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['app_meta', 'settings', 'users', 'sessions', 'login_attempts', 'room_types', 'rooms',
    'room_blocks', 'rate_plans', 'extras', 'sources', 'guests', 'guest_notes', 'reservations', 'reservation_extras',
    'housekeeping_tasks', 'handover_notes', 'notifications', 'notification_reads', 'daily_stats', 'revenue',
    'activity_log', 'payments', 'invoices', 'outbox', 'password_resets']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
END $$;

INSERT INTO app_meta (key, value) VALUES ('schema_version', '2') ON CONFLICT (key) DO NOTHING;
